	// keeps for it. Set only when one exists: an id is never made up, as with
	// gen_ai.conversation.id.
	RiusCompactionID = "rius.compaction.id"

	// A size, not content, like rius.context.sizes: deliberately absent from
	// CONTENT_ATTRIBUTES, so it survives masking and capture_content=False and
	// a reader can see how big the summary was when its text is withheld.
	RiusCompactionSummaryBytes = "rius.compaction.summary.bytes"

	// What the summary said, for a summarize compaction. Content in the same
	// sense messages are: a summary restates the conversation, so it is on
	// CONTENT_ATTRIBUTES and is masked or stripped at export. Never on a
	// pending snapshot, since it exists only once the compaction ran.
	RiusCompactionSummary = "rius.compaction.summary"

	// --- Span event names ---
	// First streamed token/chunk arrived. The standard signal is the span
	// attribute gen_ai.response.time_to_first_chunk, which the SDKs emit. The
	// Rius backend keeps gen_ai.first_token as the name of the event it
	// stores. A recorded first-chunk event (OpenInference's or the Vercel AI
	// SDK's) is renamed to it and keeps its own time. For a span with none,
	// the backend synthesizes the event from
	// gen_ai.response.time_to_first_chunk, at span start plus the duration
	// and never after the span's end; that clamp applies only to an event it
	// creates. Producers need not send it. The constant stays, deprecated,
	// until a major release.
	//
	// Deprecated: replaced by the gen_ai.response.time_to_first_chunk span attribute.
	GenAIFirstTokenEvent = "gen_ai.first_token"

	// A compaction that happens inside one request, with no step of its own:
	// the provider edits the context as part of the call, or the agent's hook
	// reports it while the call is open. It is an event on that LLM span and
	// carries the rius.compaction.* attributes. A compaction that is a step of
	// its own is a CHAIN span with gen_ai.operation.name "compaction" instead,
	// never both for the same compaction. The first LLM call after either sets
	// gen_ai.conversation.compacted.
	RiusCompactionEvent = "rius.compaction"

	// --- Pending (partial) spans ---
	// Marks the content-free snapshot exported at span START; the backend maps it
	// to Finished=0 and the real span replaces it at end. This key knowingly bends
	// the convention-native rule (no vendor namespace): OpenTelemetry has NO
	// pending-span mechanism to align with (spec #3732/#4646, semconv #2133, all
	// open, none planned), and the only shipping precedent (Logfire's
	// logfire.span_type) is equally vendor-namespaced. Spelled glassflow.span.pending
	// before the vendor keys moved under rius.*; the backend reads both spellings
	// for as long as pre-rename SDK versions are in the field.
	RiusSpanPending = "rius.span.pending"

	// --- Another SDK's tracer provider in the process ---
	// On a span: its parent is local to this process, yet rius never received
	// it, so the trace arrives without that parent. Remote parents are never
	// flagged.
	RiusParentForeign = "rius.parent.foreign"

